import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";

function Card({ title, action, children }) {
  return (
    <div
      style={{
        background: "white",
        border: "1px solid #e2e8f0",
        borderRadius: 16,
        padding: 16,
      }}
    >
      <div
        style={{
          fontWeight: 900,
          marginBottom: 12,
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 12,
        }}
      >
        <div>{title}</div>
        {action ? <div>{action}</div> : null}
      </div>

      {children}
    </div>
  );
}

const btnDark = {
  borderRadius: 14,
  border: "1px solid #0f172a",
  background: "#0f172a",
  color: "white",
  padding: "10px 18px",
  fontWeight: 900,
  cursor: "pointer",
  boxShadow: "0 1px 0 rgba(0,0,0,0.15)",
};

const btnDanger = {
  borderRadius: 12,
  border: "1px solid #ef4444",
  background: "#ef4444",
  color: "white",
  padding: "10px 12px",
  fontWeight: 900,
  cursor: "pointer",
};

const btnLight = {
  borderRadius: 14,
  border: "1px solid #cbd5e1",
  background: "white",
  color: "#0f172a",
  padding: "10px 18px",
  fontWeight: 900,
  cursor: "pointer",
};

export default function AdminDashboard() {
  const [students, setStudents] = useState([]);

  // edit mode
  const [selectedId, setSelectedId] = useState(null);

  // form fields
  const [Fname, setFname] = useState("");
  const [Lname, setLname] = useState("");
  const [Phone, setPhone] = useState("");
  const [Address, setAddress] = useState("");

  // delete confirm modal
  const [confirmId, setConfirmId] = useState(null);

  const showError = (message) => alert("Error: " + message);
  const showSuccess = (message) => alert("Success: " + message);

  const clearForm = () => {
    setSelectedId(null);
    setFname("");
    setLname("");
    setPhone("");
    setAddress("");
  };

  // READ
  const getStudents = async () => {
    try {
      const response = await axios.get("http://localhost:5000/students");
      if (response.status === 200) setStudents(response.data);
      if (response.status === 204) setStudents([]);
    } catch (err) {
      showError(err.response?.data?.message || "Error loading students.");
    }
  };

  // initial load
  useEffect(() => {
    getStudents();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const canSave = useMemo(() => {
    return Fname.trim() && Lname.trim() && Phone.trim() && Address.trim();
  }, [Fname, Lname, Phone, Address]);

  // CREATE
  const addStudent = async () => {
    const fn = Fname.trim();
    const ln = Lname.trim();
    const ph = Phone.trim();
    const ad = Address.trim();

    if (!fn || !ln || !ph || !ad) {
      showError("Please fill in all fields before adding a student.");
      return;
    }

    const studentToAdd = { Fname: fn, Lname: ln, Phone: ph, Address: ad };

    try {
      const response = await axios.post(
        "http://localhost:5000/students",
        studentToAdd
      );

      if (response.status === 201 || response.status === 200) {
        showSuccess(response.data?.message || "Student added.");
        clearForm();
        await getStudents(); // best practice: refresh from DB
      }
    } catch (err) {
      showError(err.response?.data?.message || "Error adding student.");
    }
  };

  // EDIT: load student into form
  const startEdit = (student) => {
    setSelectedId(student.id);
    setFname(student.Fname || "");
    setLname(student.Lname || "");
    setPhone(student.Phone || "");
    setAddress(student.Address || "");
  };

  // UPDATE
  const updateStudent = async () => {
    const fn = Fname.trim();
    const ln = Lname.trim();
    const ph = Phone.trim();
    const ad = Address.trim();

    if (!fn || !ln || !ph || !ad) {
      showError("Please fill in all fields before updating a student.");
      return;
    }

    if (!selectedId) {
      showError("Click Edit on a student first.");
      return;
    }

    const studentToUpdate = { Fname: fn, Lname: ln, Phone: ph, Address: ad };

    try {
      const response = await axios.put(
        `http://localhost:5000/students/${selectedId}`,
        studentToUpdate
      );

      if (response.status === 200) {
        showSuccess(response.data?.message || "Student updated.");
        clearForm();
        await getStudents();
      }
    } catch (err) {
      showError(err.response?.data?.message || "Error updating student.");
    }
  };

  // DELETE (confirmed)
  const confirmDelete = async () => {
    if (!confirmId) return;

    try {
      const response = await axios.delete(
        `http://localhost:5000/students/${confirmId}`
      );

      if (response.status === 200) {
        showSuccess(response.data?.message || "Student deleted.");
        setConfirmId(null);

        // if deleting the same student you were editing
        if (selectedId === confirmId) clearForm();

        await getStudents();
      }
    } catch (err) {
      showError(err.response?.data?.message || "Error deleting student.");
    }
  };

  return (
    <div style={{ display: "grid", gap: 16 }}>
      <Card
        title={
          selectedId
            ? `Admin — Update Student (ID: ${selectedId})`
            : "Admin — Add Student"
        }
        action={
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
            <button onClick={getStudents} type="button" style={btnDark}>
              Refresh
            </button>
            <button onClick={clearForm} type="button" style={btnLight}>
              Clear
            </button>
          </div>
        }
      >
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))",
            gap: 10,
            alignItems: "end",
          }}
        >
          <label style={{ display: "grid", gap: 6 }}>
            <span style={{ fontSize: 12, color: "#64748b", fontWeight: 800 }}>
              First name
            </span>
            <input
              value={Fname}
              onChange={(e) => setFname(e.target.value)}
              style={{
                borderRadius: 12,
                border: "1px solid #e2e8f0",
                padding: "10px 12px",
              }}
            />
          </label>

          <label style={{ display: "grid", gap: 6 }}>
            <span style={{ fontSize: 12, color: "#64748b", fontWeight: 800 }}>
              Last name
            </span>
            <input
              value={Lname}
              onChange={(e) => setLname(e.target.value)}
              style={{
                borderRadius: 12,
                border: "1px solid #e2e8f0",
                padding: "10px 12px",
              }}
            />
          </label>

          <label style={{ display: "grid", gap: 6 }}>
            <span style={{ fontSize: 12, color: "#64748b", fontWeight: 800 }}>
              Phone
            </span>
            <input
              value={Phone}
              onChange={(e) => setPhone(e.target.value)}
              style={{
                borderRadius: 12,
                border: "1px solid #e2e8f0",
                padding: "10px 12px",
              }}
            />
          </label>

          <label style={{ display: "grid", gap: 6 }}>
            <span style={{ fontSize: 12, color: "#64748b", fontWeight: 800 }}>
              Address
            </span>
            <input
              value={Address}
              onChange={(e) => setAddress(e.target.value)}
              style={{
                borderRadius: 12,
                border: "1px solid #e2e8f0",
                padding: "10px 12px",
              }}
            />
          </label>

          <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
            <button
              onClick={addStudent}
              type="button"
              disabled={!canSave || !!selectedId}
              style={{
                borderRadius: 12,
                border: "1px solid #0f172a",
                background: !canSave || selectedId ? "#94a3b8" : "#0f172a",
                color: "white",
                padding: "10px 12px",
                fontWeight: 900,
                cursor: !canSave || selectedId ? "not-allowed" : "pointer",
                minWidth: 110,
              }}
              title={
                selectedId
                  ? "Clear form to add a new student"
                  : "Add new student"
              }
            >
              Add
            </button>

            <button
              onClick={updateStudent}
              type="button"
              disabled={!canSave || !selectedId}
              style={{
                borderRadius: 12,
                border: "1px solid #0f172a",
                background: !canSave || !selectedId ? "#94a3b8" : "#0f172a",
                color: "white",
                padding: "10px 12px",
                fontWeight: 900,
                cursor: !canSave || !selectedId ? "not-allowed" : "pointer",
                minWidth: 110,
              }}
              title={!selectedId ? "Click Edit on a student first" : "Update"}
            >
              Update
            </button>
          </div>
        </div>

        <div style={{ marginTop: 10, fontSize: 12, color: "#64748b" }}>
          Tip: Click <b>Edit</b> on a student to load their data, then click{" "}
          <b>Update</b>. Click <b>Clear</b> to exit edit mode.
        </div>
      </Card>

      <Card title="Current Students">
        <div style={{ display: "grid", gap: 8 }}>
          {students.map((s) => (
            <div
              key={s.id}
              style={{
                display: "grid",
                gridTemplateColumns: "80px 1fr 110px 150px",
                gap: 10,
                alignItems: "center",
                border: "1px solid #e2e8f0",
                borderRadius: 12,
                padding: 10,
                background: selectedId === s.id ? "#f8fafc" : "white",
              }}
            >
              <div style={{ fontWeight: 900 }}>{s.id}</div>

              <div style={{ display: "grid", gap: 2 }}>
                <div style={{ fontWeight: 800 }}>
                  {s.Fname} {s.Lname}
                </div>
                <div style={{ fontSize: 12, color: "#64748b" }}>
                  {s.Phone || "—"} • {s.Address || "—"}
                </div>
              </div>

              <button
                type="button"
                onClick={() => startEdit(s)}
                style={{
                  ...btnLight,
                  padding: "10px 12px",
                  justifySelf: "end",
                }}
              >
                Edit
              </button>

              <button
                type="button"
                onClick={() => setConfirmId(s.id)}
                style={{ ...btnDanger, justifySelf: "end" }}
              >
                Delete
              </button>
            </div>
          ))}
        </div>
      </Card>

      {confirmId && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(15,23,42,0.6)",
            display: "grid",
            placeItems: "center",
            zIndex: 50,
            padding: 16,
          }}
          onClick={() => setConfirmId(null)}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{
              width: "100%",
              maxWidth: 380,
              background: "white",
              borderRadius: 16,
              border: "1px solid #e2e8f0",
              padding: 20,
              boxShadow: "0 10px 30px rgba(0,0,0,.15)",
            }}
          >
            <div style={{ fontWeight: 900, fontSize: 18 }}>Delete student?</div>
            <div style={{ marginTop: 8, fontSize: 14, color: "#64748b" }}>
              This action cannot be undone.
            </div>

            <div
              style={{
                marginTop: 18,
                display: "flex",
                justifyContent: "flex-end",
                gap: 10,
              }}
            >
              <button
                type="button"
                onClick={() => setConfirmId(null)}
                style={{
                  borderRadius: 12,
                  border: "1px solid #e2e8f0",
                  background: "white",
                  padding: "10px 12px",
                  fontWeight: 900,
                  cursor: "pointer",
                }}
              >
                Cancel
              </button>

              <button type="button" onClick={confirmDelete} style={btnDanger}>
                Delete
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
